-- 444 mock listening clips: switch to adult voices + pauses after labels.
-- STAGED ONLY. Audio must be uploaded and all 15 timing resources deployed first.
-- Run against the production jlas schema; no exam visibility/answers/scores changed.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP TEMPORARY TABLE IF EXISTS jlpt_adult_audio_plan;
CREATE TEMPORARY TABLE jlpt_adult_audio_plan (
 question_id BIGINT UNSIGNED PRIMARY KEY, clip_id BIGINT UNSIGNED UNIQUE,
 segment_id BIGINT UNSIGNED UNIQUE, exam_code VARCHAR(50) NOT NULL,
 mondai_number INT NOT NULL, question_number INT NOT NULL,
 old_url VARCHAR(1000) NOT NULL,new_url VARCHAR(1000) NOT NULL,
 ja_sha CHAR(64) NOT NULL,vi_sha CHAR(64) NOT NULL
) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;
SELECT COUNT(*) INTO @jlpt_adult_audio_matched
FROM jlpt_adult_audio_plan a
JOIN jlpt_audio_clip c ON c.id=a.clip_id AND c.question_id=a.question_id
JOIN jlpt_question q ON q.id=c.question_id AND q.mondai_id=c.mondai_id AND q.question_number=a.question_number
JOIN jlpt_mondai m ON m.id=c.mondai_id AND m.mondai_number=a.mondai_number
JOIN jlpt_part p ON p.id=m.part_id AND p.part_code='listening'
JOIN jlpt_exam e ON e.id=p.exam_id AND BINARY e.exam_code=BINARY a.exam_code
JOIN jlpt_transcript_segment t ON t.id=a.segment_id AND t.audio_clip_id=c.id
WHERE (BINARY c.audio_url=BINARY a.old_url OR BINARY c.audio_url=BINARY a.new_url)
 AND SHA2(t.text_ja,256)=a.ja_sha AND SHA2(t.text_vi,256)=a.vi_sha;

-- If any source or identifier differs, update ZERO clips; investigate before retrying.
UPDATE jlpt_audio_clip c
JOIN jlpt_adult_audio_plan a ON a.clip_id=c.id AND a.question_id=c.question_id
JOIN jlpt_transcript_segment t ON t.id=a.segment_id AND t.audio_clip_id=c.id
SET c.audio_url=a.new_url
WHERE @jlpt_adult_audio_matched=444 AND BINARY c.audio_url=BINARY a.old_url
 AND SHA2(t.text_ja,256)=a.ja_sha AND SHA2(t.text_vi,256)=a.vi_sha;
SET @jlpt_adult_audio_updated=ROW_COUNT();
SELECT @jlpt_adult_audio_matched AS matched_sources_expected_444,
 @jlpt_adult_audio_updated AS updated_this_run,
 SUM(BINARY c.audio_url=BINARY a.new_url) AS new_urls_expected_444
FROM jlpt_adult_audio_plan a JOIN jlpt_audio_clip c ON c.id=a.clip_id;
COMMIT;
DROP TEMPORARY TABLE jlpt_adult_audio_plan;
